package main
import("flag";"fmt";"log";"os";"time";"edgesync/pkg/kv";"edgesync/pkg/lsm")
func main(){dir:=flag.String("data","./data/checker","data directory");duration:=flag.Duration("duration",10*time.Second,"write/read verification duration");flag.Parse();s,e:=lsm.Open(lsm.Options{Dir:*dir,SyncWrites:true});if e!=nil{log.Fatal(e)};defer s.Close();deadline:=time.Now().Add(*duration);i:=0;for time.Now().Before(deadline){k:=[]byte(fmt.Sprintf("durability:%d",i));v:=[]byte(fmt.Sprintf("value:%d",i));if e=s.Put(k,v);e!=nil{log.Fatal(e)};got,e:=s.Get(k);if e!=nil||string(got)!=string(v){log.Fatalf("verification failed key=%s got=%s err=%v",k,got,e)};i++};if e=s.Close();e!=nil{log.Fatal(e)};s,e=lsm.Open(lsm.Options{Dir:*dir,SyncWrites:true});if e!=nil{log.Fatal(e)};defer s.Close();for n:=0;n<i;n++{k:=[]byte(fmt.Sprintf("durability:%d",n));v,e:=s.Get(k);if e!=nil||string(v)!=fmt.Sprintf("value:%d",n){log.Fatalf("restart recovery failed key=%s err=%v",k,e)}};fmt.Printf("PASS: %d writes verified before and after restart\n",i);_ = os.Stdout;_ = kv.ErrNotFound}
